/**
 * On screens lower than this width, x, y and width declarations will be ignored and the window stretched across the full width.
 * 0 disables this behaviour altogether.
 * @type {number}
 */
const FULLSCREEN_THRESHOLD = 640;

/**
 * ID (excluding # symbol) of the parent block element to create all windows within.
 * @type {string}
 */
const WINDOWS_PARENT_ELEMENT_ID = 'desktop';

/**
 * Path to a JSON file containing a dictionary of windows keys and their associated content URLs.
 * This dictionary must exist for security reasons.
 * @example {"home": "home", "about": "pages/aboutme.html", "me_irl": "img/me.jpg"}
 * @type {string}
 */
const WINDOWS_REGISTRY_FILE = 'config/win-urls.json';

/**
 * Path to a html file to be displayed in case a key is missing in the WINDOWS_REGISTRY_FILE.
 * @type {string}
 */
const WINDOWS_404_ERROR_FILE = 'pages/win-404.html';

class Window{#css={minWinWidth:0,borderWidth:0,titleHeight:0};#key=null;#mdown={mx:0,my:0,x:0,y:0,w:0,h:0};#titleBar=null;#titleBarText=null;#iframe=null;#desktopRect={x:0,y:0,w:0,h:0};#initialDim={w:null,h:null};#restoredFromSaveData=false;static mouseEvent={target:null,type:null,direction:null};static topZIndex=0;static windowList=[];constructor(key,options={}){this.#key=key;const parentElement=document.getElementById(WINDOWS_PARENT_ELEMENT_ID);if(!parentElement){console.error(`Failed to find any element with id="#${WINDOWS_PARENT_ELEMENT_ID}" in which to create windows within.`);return}const cs=window.getComputedStyle(document.body);this.#css={minWinWidth:parseInt(cs.getPropertyValue("--win-min-width")),borderWidth:parseInt(cs.getPropertyValue("--win-border-width")),titleHeight:parseInt(cs.getPropertyValue("--win-title-height"))};if(options.hasOwnProperty("width"))this.#initialDim.w=Math.max(options.width,this.#css.minWinWidth);if(options.hasOwnProperty("height"))this.#initialDim.h=Math.max(options.height,this.#css.titleHeight);const defaults={title:"loading…",width:640,height:480,x:20,y:20};options={...defaults,...options,...{url:Window.registry[key]}};if(options.private?.hasOwnProperty("restoredFromSaveData"))this.#restoredFromSaveData=options.private.restoredFromSaveData;if(options.url===undefined){console.warn(`Could not create window with key '${key}' because that key is missing in '${WINDOWS_REGISTRY_FILE}'.`,options.url);options.url=WINDOWS_404_ERROR_FILE}if(FULLSCREEN_THRESHOLD>0&&parentElement.clientWidth<=FULLSCREEN_THRESHOLD){options.x=0;options.y=0;options.width=65535}this.html=document.createElement("article");this.html.classList.add("window");this.html.style.cssText=`width:${options.width}px;height:${options.height}px;left:${options.x}px;top:${options.y}px;z-index:${Window.topZIndex++};`;this.html.addEventListener("mousedown",()=>{this.html.style.zIndex=Window.topZIndex++});parentElement.appendChild(this.html);this.updateDesktopRect();this.#clampToDesktop();this.#titleBar=document.createElement("div");this.html.appendChild(this.#titleBar);this.#titleBar.classList.add("window-title-bar");this.#titleBar.addEventListener("mousedown",e=>{const rect=this.html.getBoundingClientRect();this.#mdown={x:e.clientX-rect.left,y:e.clientY-rect.top};Window.setMouseEvent(this,"pos")});this.#titleBarText=document.createElement("h1");this.#titleBar.appendChild(this.#titleBarText);const cb=document.createElement("div");this.html.appendChild(cb);cb.classList.add("window-close-button");cb.addEventListener("click",()=>{this.html.remove();Window.windowList.splice(Window.windowList.indexOf(this),1)});this.#iframe=document.createElement("iframe");this.html.appendChild(this.#iframe);this.#iframe.classList.add("window-content");this.#iframe.src=options.url;if(options.title!=="loading…"){this.#titleBarText.innerText=options.title}else{this.#iframe.onload=()=>{try{if(!this.#iframe.contentWindow.document.title)throw"error reading iframe document title";this.#titleBarText.innerText=this.#iframe.contentWindow.document.title}catch(ex){console.warn("failed to load window title, reason:",ex);this.#titleBarText.innerText="Untitled"}}}["n","ne","e","se","s","sw","w","nw"].forEach(direction=>{let div=document.createElement("div");this.html.appendChild(div);div.classList.add("window-resize-handler",direction);div.addEventListener("mousedown",e=>{e.preventDefault();this.#mdown={mx:e.clientX,my:e.clientY,w:this.html.offsetWidth,h:this.html.offsetHeight,x:this.html.offsetLeft,y:this.html.offsetTop};Window.setMouseEvent(this,"dim",direction)})});Window.windowList.push(this)}updateDesktopRect(){const desktop=this.html.parentElement;const rect=desktop.getBoundingClientRect();this.#desktopRect={x:rect.left+window.scrollX,y:rect.top+window.scrollY,w:desktop.clientWidth,h:desktop.clientHeight}}setPos(mx,my){const relX=mx-this.#desktopRect.x;const relY=my-this.#desktopRect.y;const maxX=this.#desktopRect.w-this.html.offsetWidth;const maxY=this.#desktopRect.h-this.html.offsetHeight;let x=Math.max(0,Math.min(relX-this.#mdown.x,maxX));let y=Math.max(0,Math.min(relY-this.#mdown.y,maxY));this.html.style.left=`${x}px`;this.html.style.top=`${y}px`}setDim(mx,my){const dir=Window.mouseEvent.direction;const dx=mx-this.#mdown.mx;const dy=my-this.#mdown.my;let x=this.#mdown.x;let y=this.#mdown.y;let w=this.#mdown.w;let h=this.#mdown.h;let corners={left:x,top:y,right:x+w,bottom:y+h};if(dir.includes("w"))corners.left=x+dx;if(dir.includes("e"))corners.right=x+w+dx;if(dir.includes("n"))corners.top=y+dy;if(dir.includes("s"))corners.bottom=y+h+dy;x=corners.left;y=corners.top;w=corners.right-corners.left;h=corners.bottom-corners.top;const minWidth=this.#css.minWinWidth;const minHeight=this.#css.titleHeight+this.#css.borderWidth;if(w<minWidth){if(dir.includes("w")){x=x+w-minWidth}w=minWidth}if(h<minHeight){if(dir.includes("n")){y=y+h-minHeight}h=minHeight}if(x<0){const shift=-x;x=0;w-=shift;if(w<minWidth)w=minWidth}if(y<0){const shift=-y;y=0;h-=shift;if(h<minHeight)h=minHeight}if(x+w>this.#desktopRect.w){const shift=x+w-this.#desktopRect.w;w-=shift;if(w<minWidth){w=minWidth;x=this.#desktopRect.w-w}}if(y+h>this.#desktopRect.h){const shift=y+h-this.#desktopRect.h;h-=shift;if(h<minHeight){h=minHeight;y=this.#desktopRect.h-h}}x=Math.max(0,Math.min(x,this.#desktopRect.w-minWidth));y=Math.max(0,Math.min(y,this.#desktopRect.h-minHeight));w=Math.max(minWidth,Math.min(w,this.#desktopRect.w-x));h=Math.max(minHeight,Math.min(h,this.#desktopRect.h-y));this.html.style.left=`${x}px`;this.html.style.top=`${y}px`;this.html.style.width=`${w}px`;this.html.style.height=`${h}px`}resizeToContent(contentW,contentH){if(this.#restoredFromSaveData)return;const addW=2*this.#css.borderWidth;const addH=2*this.#css.borderWidth+this.#css.titleHeight;if(this.#initialDim.w)this.#initialDim.w-=addW;if(this.#initialDim.h)this.#initialDim.h-=addH;let currentW=parseInt(this.html.style.width)-addW;let currentH=parseInt(this.html.style.height)-addH;const posX=parseInt(this.html.style.left);const posY=parseInt(this.html.style.top);if(this.#initialDim.w&&this.#initialDim.h){const customH=this.#initialDim.w*contentH/contentW;const customW=this.#initialDim.h*contentW/contentH;const area_cH=this.#initialDim.w*customH;const area_cW=this.#initialDim.h*customW;currentW=area_cH>area_cW?this.#initialDim.w:customW;currentH=area_cH>area_cW?customH:this.#initialDim.h}else if(this.#initialDim.w){currentW=this.#initialDim.w;currentH=currentW*contentH/contentW}else if(this.#initialDim.h){currentH=this.#initialDim.h;currentW=currentH*contentW/contentH}if(currentW+addW+posX>this.#desktopRect.w){let oldW=currentW;currentW=this.#desktopRect.w-addW-posX;currentH=currentW*currentH/oldW}if(currentH+addH+posY>this.#desktopRect.h){let oldH=currentH;currentH=this.#desktopRect.h-addH-posY;currentW=currentH*currentW/oldH}currentW=Math.ceil(currentW);currentH=Math.ceil(currentH);this.html.style.width=`${currentW+addW}px`;this.html.style.height=`${currentH+addH}px`}centerToDesktop(){const centerX=Math.max(0,(this.#desktopRect.w-parseInt(this.html.style.width))/2);const centerY=Math.max(0,(this.#desktopRect.h-parseInt(this.html.style.height))/2);this.html.style.left=`${centerX}px`;this.html.style.top=`${centerY}px`}#clampToDesktop(){const desktopW=this.#desktopRect.w;const desktopH=this.#desktopRect.h;const minWidth=this.#css.minWinWidth;const minHeight=this.#css.titleHeight+2*this.#css.borderWidth;let x=parseInt(this.html.style.left)||0;let y=parseInt(this.html.style.top)||0;let w=parseInt(this.html.style.width)||minWidth;let h=parseInt(this.html.style.height)||minHeight;if(x>desktopW){x=desktopW-w}if(y>desktopH){y=desktopH-h}if(w>desktopW){w=desktopW-x}if(h>desktopH){h=desktopH-y}if(x<0){w+=x;x=0}if(x+w>desktopW){w=desktopW-x}w=Math.max(minWidth,w);x=Math.max(0,Math.min(x,desktopW-w));if(y<0){h+=y;y=0}if(y+h>desktopH){h=desktopH-y}h=Math.max(minHeight,h);y=Math.max(0,Math.min(y,desktopH-h));this.html.style.left=`${x}px`;this.html.style.top=`${y}px`;this.html.style.width=`${w}px`;this.html.style.height=`${h}px`}static setMouseEvent(target,type=null,direction=null){if(target){document.body.classList.add("window-drag-active");target.updateDesktopRect()}else{document.body.classList.remove("window-drag-active")}Window.mouseEvent.target=target;Window.mouseEvent.type=type;Window.mouseEvent.direction=direction}static getSavaData(){let r=[];Window.windowList.forEach(win=>{r.push(`${win.#key},${win.html.offsetWidth},${win.html.offsetHeight},${win.html.offsetLeft},${win.html.offsetTop},${win.html.style.zIndex}`)});return r.join(";")}static findByUrl(url){let ret=null;let topz=0;for(const win of Window.windowList){const iframe=win.html.getElementsByTagName("iframe")[0];if(iframe&&iframe.src===url){const z=parseInt(win.html.style.zIndex)||0;if(z>topz){topz=z;ret=win}}}return ret}static async initWindows(){if(Window.registry)return true;try{let url=WINDOWS_REGISTRY_FILE;url+=`?${Date.now()}`;Window.registry=await(await fetch(url)).json();if(!Window.registry)throw"malformed data"}catch(ex){console.error(`failed to load window dictionary '${WINDOWS_REGISTRY_FILE}', reason: ${ex}`);return false}if(window.location.hash){window.location.hash.substring(1).split(";").forEach(item=>{let data=item.split(",");if(!Window.registry[data[0]])return;new Window(data[0],{width:parseInt(data[1]),height:parseInt(data[2]),x:parseInt(data[3]),y:parseInt(data[4]),z:parseInt(data[5]),private:{restoredFromSaveData:true}})})}return true}}Window.initWindows();document.addEventListener("mouseup",()=>{Window.setMouseEvent(null)});document.addEventListener("mousemove",e=>{if(Window.mouseEvent.type=="pos"&&e.buttons!=0){Window.mouseEvent.target.setPos(e.clientX,e.clientY)}else if(Window.mouseEvent.type=="dim"&&e.buttons!=0){Window.mouseEvent.target.setDim(e.clientX,e.clientY)}});window.addEventListener("resize",()=>{Window.windowList.forEach(win=>{win.updateDesktopRect()})});window.addEventListener("message",e=>{if(e.origin!==window.origin){console.warn(`window communication warning: origin mismatch, should be '${window.origin}', but is`,e.origin);return}if(e.data.type==="PassClientScriptReady"){return}if(!e.data.action){console.warn("window communication warning: message without action field encountered.");return}switch(e.data.action){case"window":new Window(e.data.key,e.data);break;case"resize":Window.findByUrl(e.source.location.href)?.resizeToContent(e.data.width,e.data.height);break}});setInterval(()=>{history.replaceState(undefined,undefined,`#${Window.getSavaData()}`)},500);